p.me:
\begin{array}{c|c}
\textbf{kind of function} \amp \textbf{reason}\\
\hline
\text{continuous functions} \amp \text{small intervals have small oscillation}\\
\text{monotone functions} \amp \text{upper-lower gaps telescope}\\
\text{bounded functions with} \amp \text{discontinuity points can be covered}\\
\text{finitely many discontinuities} \amp \text{by tiny intervals}
\end{array}
